// eslint-disable
'use strict';

const logger = require('@yandex-int/yandex-logger')();
const err = new Error('Something went wrong!');

// 1. Простое сообщение
logger.info('Log message');

// 2. Сообщение с форматированием
logger.info('Found %d messages for %s', 5, 'Username');

// 3. Логируем только ошибку
logger.error(err);

// 4. Логируем ошибку и заменяем сообщение
logger.error(err, 'Custom error message');

// 5. Логируем ошибку и заменяем сообщение с форматированием
logger.error(err, 'Query error: %s', 'Connection lost');

// 6. Логируем ошибку и дополнительную информацию о запросе
let req = require('./entry').req;
logger.error({ req, err }, 'Request error');

// 7. Логируем ошибку и дополнительную информацию
let data = {
    query: 'SELECT * FROM nowhere;',
};
let user = {
    id: 123,
};
logger.error({ err, user, data }, 'Query error: %s', 'Connection lost');
